#!/bin/bash
# cold (fresh RVT_CORE_CACHE) cProfile of the viewer conversion of corpus corpus-008 on host2 (geometry stage 1109 s); top cumulative/tottime in ~/offload/prof_corpus.txt there
cd ~/src/rvt-viewer
~/.local/share/offload/h2run run profcorpus --env occ --dir /home/user1/src/rvt-viewer -- bash -c "rm -rf /home/user1/.cache/rvt-viewer/prof-work /home/user1/offload/profcache; RVT_NO_GEOM_CACHE=1 RVT_CORE_CACHE=/home/user1/offload/profcache RVT_CAPPED=1 python -c \"import cProfile,pstats,sys; sys.path.insert(0,'.'); from rvtviewer.cli import main; cProfile.run('main([\\\"convert\\\",\\\"/home/user1/scratch-famtest/corpus/corpus-008.rvt\\\",\\\"/home/user1/.cache/rvt-viewer/prof-work\\\"])','/home/user1/offload/prof_corpus.pstats')\"; python -c \"import pstats; p=pstats.Stats('/home/user1/offload/prof_corpus.pstats'); p.sort_stats('tottime').print_stats(25)\" > /home/user1/offload/prof_corpus.txt" 2>&1 | tail -2
